def stock_report(self) -> Dict[str, int]:
        """Return a mapping of SKU to available quantity for SKUs with positive availability."""
        report: Dict[str, int] = {}
        # Iterate over SKUs known to the ledger (those with positive on-hand) and
        # include only those with positive available quantity.
        for sku in self._ledger:
            avail = self._ledger.available(sku)
            if avail > 0:
                report[sku] = avail
        return report
